mapper.select:
select id, person_id, title, dir, photo_count, bytes, cover_path, note, sort, hidden, mtime
from media_album
where id = #{id}

select p.id, p.album_id, p.seq, p.rel_path, p.bytes, p.w, p.h, p.is_big, p.hidden,
       p.missing, p.last_seen, p.content_hash
from media_photo p
where p.album_id = #{albumId}
order by p.seq asc
limit #{limit}

select count(*)
from media_album
where dir = #{dir} and id <> #{excludeId}

select p.id, p.root_id, p.album_id, p.seq, p.rel_path, p.bytes, p.w, p.h, p.is_big, p.hidden, p.missing, p.last_seen, p.content_hash from media_photo p where p.missing = 1
and p.album_id = #{albumId}
order by p.last_seen asc, p.album_id asc, p.seq asc, p.id asc

mapper.delete:
delete from media_photo where missing = 1

    and id in
    #{it}

delete from media_video where missing = 1

    and id in
    #{it}
